import * as fs from 'fs';
import * as path from 'path';
import { v4 as uuidv4 } from 'uuid';
import { Document } from '../shared/types';
import { PersistenceService } from './persistence-service';
import { logger } from './logger';

const SERVICE = 'document-service';
const DOCUMENTS_META = 'documents-meta.json';

export class DocumentService {
  private persistence: PersistenceService;

  constructor(persistence: PersistenceService) {
    this.persistence = persistence;
  }

  /** List all imported documents. */
  listDocuments(): Document[] {
    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META);
    logger.debug(SERVICE, 'Listing documents', { count: docs?.length ?? 0 });
    return docs ?? [];
  }

  /** Import a file from the given path. */
  importDocument(filePath: string): Document {
    if (!fs.existsSync(filePath)) {
      logger.error(SERVICE, `File not found: ${filePath}`);
      throw new Error(`File not found: ${filePath}`);
    }

    const filename = path.basename(filePath);
    const content = fs.readFileSync(filePath, 'utf-8');
    const stats = fs.statSync(filePath);

    const doc: Document = {
      id: uuidv4(),
      title: filename.replace(/\.[^.]+$/, ''),
      filename,
      importedAt: new Date().toISOString(),
      size: stats.size,
      status: 'imported',
    };

    // Copy file to data directory
    this.persistence.copyFileToDocuments(filePath, filename);

    // Store content for indexing
    this.persistence.writeText(`content/${doc.id}.txt`, content);

    // Update metadata
    const docs = this.listDocuments();
    docs.push(doc);
    this.persistence.writeJson(DOCUMENTS_META, docs);

    logger.info(SERVICE, 'Document imported', {
      documentId: doc.id,
      filename: doc.filename,
      size: doc.size,
    });
    return doc;
  }

  /** Get a single document by ID. */
  getDocument(id: string): Document | null {
    const docs = this.listDocuments();
    return docs.find(d => d.id === id) ?? null;
  }

  /** Get the text content of a document. */
  getDocumentContent(id: string): string | null {
    return this.persistence.readText(`content/${id}.txt`);
  }

  /** Update a document's metadata. */
  updateDocument(id: string, updates: Partial<Document>): Document | null {
    const docs = this.listDocuments();
    const index = docs.findIndex(d => d.id === id);
    if (index === -1) return null;

    docs[index] = { ...docs[index], ...updates };
    this.persistence.writeJson(DOCUMENTS_META, docs);
    logger.info(SERVICE, 'Document updated', { documentId: id, fields: Object.keys(updates) });
    return docs[index];
  }

  /** Delete a document by ID. */
  deleteDocument(id: string): boolean {
    const docs = this.listDocuments();
    const doc = docs.find(d => d.id === id);
    if (!doc) return false;

    this.persistence.deleteFromDocuments(doc.filename);

    const updated = docs.filter(d => d.id !== id);
    this.persistence.writeJson(DOCUMENTS_META, updated);
    logger.info(SERVICE, 'Document deleted', { documentId: id, filename: doc.filename });
    return true;
  }
}
import { FeedbackEntry, FeedbackRating } from '../shared/types';
import { PersistenceService } from './persistence-service';
import { logger } from './logger';

const SERVICE = 'feedback-service';
export const FEEDBACK_FILE = 'feedback.json';
const RATINGS: readonly FeedbackRating[] = ['up', 'down'];

/**
 * Stores helpful / not-helpful ratings for answers in feedback.json.
 * One rating per answer: rating the same answer again replaces the earlier rating.
 */
export class FeedbackService {
  constructor(
    private persistence: PersistenceService,
    /** Returns true when an answer id exists; ratings for unknown answers are rejected. */
    private answerExists: (answerId: string) => boolean,
  ) {}

  submit(answerId: unknown, rating: unknown): FeedbackEntry {
    if (typeof answerId !== 'string' || answerId.trim() === '') {
      logger.warn(SERVICE, 'Rejected feedback: invalid answerId', { answerId: String(answerId) });
      throw new Error('answerId must be a non-empty string');
    }
    if (!RATINGS.includes(rating as FeedbackRating)) {
      logger.warn(SERVICE, 'Rejected feedback: invalid rating', { answerId, rating: String(rating) });
      throw new Error(`rating must be 'up' or 'down', got ${JSON.stringify(rating)}`);
    }
    if (!this.answerExists(answerId)) {
      logger.warn(SERVICE, 'Rejected feedback: unknown answer', { answerId });
      throw new Error(`No answer with id ${answerId}`);
    }

    const entry: FeedbackEntry = {
      answerId,
      rating: rating as FeedbackRating,
      timestamp: new Date().toISOString(),
    };
    const others = this.list().filter(f => f.answerId !== answerId);
    this.persistence.writeJson(FEEDBACK_FILE, [...others, entry]);
    logger.info(SERVICE, 'Feedback submitted', { answerId, rating: entry.rating, total: others.length + 1 });
    return entry;
  }

  list(): FeedbackEntry[] {
    const entries = this.persistence.readJson<FeedbackEntry[]>(FEEDBACK_FILE) ?? [];
    logger.debug(SERVICE, 'Listing feedback', { count: entries.length });
    return entries;
  }
}
import { v4 as uuidv4 } from 'uuid';
import { Chunk, Document } from '../shared/types';
import { PersistenceService } from './persistence-service';
import { logger } from './logger';

const SERVICE = 'indexing-service';
const INDEX_META = 'index-meta.json';
const CHUNKS_DIR = 'chunks';

interface IndexStatus {
  status: 'idle' | 'indexing' | 'ready' | 'error';
  currentIndexed: number;
  totalDocuments: number;
  lastIndexed: string | null;
}

export class IndexingService {
  private persistence: PersistenceService;

  constructor(persistence: PersistenceService) {
    this.persistence = persistence;
  }

  /** Start indexing documents. If documentId is provided, index only that document. */
  async startIndexing(documentId?: string): Promise<IndexStatus> {
    const status = this.getStatus();

    if (documentId) {
      const content = this.persistence.readText(`content/${documentId}.txt`);
      if (!content) {
        logger.error(SERVICE, `Content not found for document: ${documentId}`);
        return { ...status, status: 'error' };
      }
      const chunks = this.chunkDocument(documentId, content);
      this.persistence.writeJson(`${CHUNKS_DIR}/${documentId}.json`, chunks);
      logger.info(SERVICE, 'Single document indexed', {
        documentId,
        chunkCount: chunks.length,
      });
      return this.getStatus();
    }

    const docsMeta = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};

    let indexedCount = 0;
    for (const doc of docsMeta) {
      if (chunksMeta[doc.id]) continue;

      const content = this.persistence.readText(`content/${doc.id}.txt`);
      if (!content) continue;

      const chunks = this.chunkDocument(doc.id, content);
      this.persistence.writeJson(`${CHUNKS_DIR}/${doc.id}.json`, chunks);
      chunksMeta[doc.id] = chunks.map(c => c.id);
      indexedCount++;
      logger.info(SERVICE, 'Document indexed', {
        documentId: doc.id,
        chunkCount: chunks.length,
      });
    }

    this.persistence.writeJson(INDEX_META, chunksMeta);
    logger.info(SERVICE, 'Batch indexing complete', {
      totalDocs: docsMeta.length,
      newlyIndexed: indexedCount,
    });
    return this.getStatus();
  }

  /** Get current indexing status. */
  getStatus(): IndexStatus {
    const docs = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};

    const currentIndexed = Object.keys(chunksMeta).length;
    const totalDocuments = docs.length;
    const isReady = currentIndexed === totalDocuments && totalDocuments > 0;

    return {
      status: isReady ? 'ready' : currentIndexed > 0 ? 'indexing' : 'idle',
      currentIndexed,
      totalDocuments,
      lastIndexed: new Date().toISOString(),
    };
  }

  /** Get all chunks for a document. */
  getChunksForDocument(documentId: string): Chunk[] {
    return this.persistence.readJson<Chunk[]>(`${CHUNKS_DIR}/${documentId}.json`) ?? [];
  }

  /** Get all chunks across all documents. */
  getAllChunks(): Chunk[] {
    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
    const allChunks: Chunk[] = [];

    for (const docId of Object.keys(chunksMeta)) {
      const chunks = this.getChunksForDocument(docId);
      allChunks.push(...chunks);
    }

    return allChunks;
  }

  /** Split a document into chunks of ~500 characters at paragraph boundaries. */
  private chunkDocument(documentId: string, content: string): Chunk[] {
    const CHUNK_SIZE = 500;
    const chunks: Chunk[] = [];

    const paragraphs = content.split(/\n\s*\n/).filter(p => p.trim().length > 0);

    let buffer = '';
    let chunkIndex = 0;

    for (const para of paragraphs) {
      if (buffer.length + para.length > CHUNK_SIZE && buffer.length > 0) {
        chunks.push(this.createChunk(documentId, chunkIndex++, buffer.trim()));
        buffer = para;
      } else {
        buffer += (buffer ? '\n\n' : '') + para;
      }
    }

    if (buffer.trim()) {
      chunks.push(this.createChunk(documentId, chunkIndex, buffer.trim()));
    }

    return chunks;
  }

  private createChunk(documentId: string, index: number, content: string): Chunk {
    return {
      id: uuidv4(),
      documentId,
      content,
      index,
      metadata: {
        charCount: String(content.length),
        wordCount: String(content.split(/\s+/).length),
      },
    };
  }
}
/**
 * Structured logging module for the Knowledge Base application.
 *
 * Provides log levels, timestamps, and structured JSON output for
 * all services. Replaces raw console.log calls with consistent,
 * machine-parseable log entries.
 */

export enum LogLevel {
  DEBUG = 'DEBUG',
  INFO = 'INFO',
  WARN = 'WARN',
  ERROR = 'ERROR',
}

interface LogEntry {
  timestamp: string;
  level: LogLevel;
  service: string;
  message: string;
  data?: Record<string, unknown>;
}

class Logger {
  private minLevel: LogLevel;
  private static readonly LEVEL_ORDER: LogLevel[] = [
    LogLevel.DEBUG,
    LogLevel.INFO,
    LogLevel.WARN,
    LogLevel.ERROR,
  ];

  constructor(minLevel: LogLevel = LogLevel.DEBUG) {
    this.minLevel = minLevel;
  }

  private shouldLog(level: LogLevel): boolean {
    const minIdx = Logger.LEVEL_ORDER.indexOf(this.minLevel);
    const levelIdx = Logger.LEVEL_ORDER.indexOf(level);
    return levelIdx >= minIdx;
  }

  private emit(entry: LogEntry): void {
    const output = JSON.stringify(entry);
    switch (entry.level) {
      case LogLevel.ERROR:
        console.error(output);
        break;
      case LogLevel.WARN:
        console.warn(output);
        break;
      default:
        console.log(output);
        break;
    }
  }

  private log(level: LogLevel, service: string, message: string, data?: Record<string, unknown>): void {
    if (!this.shouldLog(level)) return;

    const entry: LogEntry = {
      timestamp: new Date().toISOString(),
      level,
      service,
      message,
    };

    if (data && Object.keys(data).length > 0) {
      entry.data = data;
    }

    this.emit(entry);
  }

  debug(service: string, message: string, data?: Record<string, unknown>): void {
    this.log(LogLevel.DEBUG, service, message, data);
  }

  info(service: string, message: string, data?: Record<string, unknown>): void {
    this.log(LogLevel.INFO, service, message, data);
  }

  warn(service: string, message: string, data?: Record<string, unknown>): void {
    this.log(LogLevel.WARN, service, message, data);
  }

  error(service: string, message: string, data?: Record<string, unknown>): void {
    this.log(LogLevel.ERROR, service, message, data);
  }

  /** Create a child logger scoped to a specific service. */
  forService(serviceName: string): ServiceLogger {
    return new ServiceLogger(this, serviceName);
  }
}

class ServiceLogger {
  private logger: Logger;
  private serviceName: string;

  constructor(logger: Logger, serviceName: string) {
    this.logger = logger;
    this.serviceName = serviceName;
  }

  debug(message: string, data?: Record<string, unknown>): void {
    this.logger.debug(this.serviceName, message, data);
  }

  info(message: string, data?: Record<string, unknown>): void {
    this.logger.info(this.serviceName, message, data);
  }

  warn(message: string, data?: Record<string, unknown>): void {
    this.logger.warn(this.serviceName, message, data);
  }

  error(message: string, data?: Record<string, unknown>): void {
    this.logger.error(this.serviceName, message, data);
  }
}

/** Singleton logger instance for the application. */
export const logger = new Logger(
  (process.env.LOG_LEVEL as LogLevel) ?? LogLevel.DEBUG
);

