import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { logger, LogLevel, ServiceLogger } from '../../src/services/logger';

let log: ReturnType<typeof vi.spyOn>;
let warn: ReturnType<typeof vi.spyOn>;
let error: ReturnType<typeof vi.spyOn>;

beforeEach(() => {
  log = vi.spyOn(console, 'log').mockImplementation(() => {});
  warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
  error = vi.spyOn(console, 'error').mockImplementation(() => {});
});
afterEach(() => vi.restoreAllMocks());

const parsed = (spy: ReturnType<typeof vi.spyOn>, call = 0) => JSON.parse(spy.mock.calls[call][0] as string);

describe('logger', () => {
  it('debug and info go to console.log as structured JSON', () => {
    logger.debug('svc', 'debug msg', { a: 1 });
    logger.info('svc', 'info msg');
    expect(log).toHaveBeenCalledTimes(2);
    const d = parsed(log, 0);
    expect(d).toEqual({ timestamp: expect.any(String), level: 'DEBUG', service: 'svc', message: 'debug msg', data: { a: 1 } });
    expect(Number.isNaN(Date.parse(d.timestamp))).toBe(false);
    expect(parsed(log, 1)).toMatchObject({ level: 'INFO', message: 'info msg' });
  });

  it('warn goes to console.warn and error to console.error', () => {
    logger.warn('svc', 'careful', { x: 'y' });
    logger.error('svc', 'boom');
    expect(parsed(warn)).toMatchObject({ level: 'WARN', service: 'svc', message: 'careful', data: { x: 'y' } });
    expect(parsed(error)).toMatchObject({ level: 'ERROR', service: 'svc', message: 'boom' });
    expect(log).not.toHaveBeenCalled();
  });

  it('omits data when it is missing or empty', () => {
    logger.info('svc', 'no data');
    logger.info('svc', 'empty data', {});
    expect(parsed(log, 0)).not.toHaveProperty('data');
    expect(parsed(log, 1)).not.toHaveProperty('data');
  });

  it('drops entries below the minimum level', () => {
    const LoggerClass = logger.constructor as new (min?: LogLevel) => typeof logger;
    const warnOnly = new LoggerClass(LogLevel.WARN);
    warnOnly.debug('svc', 'hidden');
    warnOnly.info('svc', 'hidden');
    warnOnly.warn('svc', 'shown');
    warnOnly.error('svc', 'shown');
    expect(log).not.toHaveBeenCalled();
    expect(warn).toHaveBeenCalledTimes(1);
    expect(error).toHaveBeenCalledTimes(1);
  });

  it('defaults to DEBUG when constructed without a level', () => {
    const LoggerClass = logger.constructor as new (min?: LogLevel) => typeof logger;
    new LoggerClass().debug('svc', 'shown');
    expect(log).toHaveBeenCalledTimes(1);
  });

  it('the singleton reads its minimum level from LOG_LEVEL', async () => {
    const prev = process.env.LOG_LEVEL;
    process.env.LOG_LEVEL = LogLevel.ERROR;
    try {
      vi.resetModules();
      const fresh = await import('../../src/services/logger');
      fresh.logger.warn('svc', 'hidden');
      fresh.logger.error('svc', 'shown');
      expect(warn).not.toHaveBeenCalled();
      expect(error).toHaveBeenCalledTimes(1);
    } finally {
      if (prev === undefined) delete process.env.LOG_LEVEL;
      else process.env.LOG_LEVEL = prev;
      vi.resetModules();
    }
  });
});

describe('ServiceLogger', () => {
  it('forService returns a logger that tags every level with the service name', () => {
    const svc = logger.forService('scoped');
    expect(svc).toBeInstanceOf(ServiceLogger);
    svc.debug('d', { n: 1 });
    svc.info('i');
    svc.warn('w');
    svc.error('e', { n: 2 });
    expect(parsed(log, 0)).toMatchObject({ level: 'DEBUG', service: 'scoped', message: 'd', data: { n: 1 } });
    expect(parsed(log, 1)).toMatchObject({ level: 'INFO', service: 'scoped', message: 'i' });
    expect(parsed(warn)).toMatchObject({ level: 'WARN', service: 'scoped', message: 'w' });
