  it('without indexed chunks: no citations, confidence 0.3', async () => {
    const { qaService } = makeServices(tempDir());
    const fallback = await qaService.ask('what is the weather');
    expect(fallback).toMatchObject({ answer: NO_DOCS, citations: [], confidence: 0.3 });
    const pattern = await qaService.ask('Explain the architecture');
    expect(pattern.answer).toMatch(/^The system uses a layered architecture/);
    expect(pattern.answer).not.toContain('Based on the document');
    expect(pattern.citations).toEqual([]);
  });

  it('cites the top two matching chunks, best first, with confidence 0.85', async () => {
    const { qaService, docs } = await indexed({
      'one.txt': 'apples only here',
      'two.txt': 'apples and bananas and cherries',
      'three.txt': 'apples and bananas',
      'four.txt': 'nothing relevant',
    });
    const r = await qaService.ask('apples bananas cherries');
    expect(r.confidence).toBe(0.85);
    expect(r.citations).toEqual([
      { documentId: docs[1].id, documentTitle: 'two', chunkIndex: 0, excerpt: 'apples and bananas and cherries' },
      { documentId: docs[2].id, documentTitle: 'three', chunkIndex: 0, excerpt: 'apples and bananas' },
    ]);
    // no pattern keyword -> generic fallback built from the first citation
    expect(r.answer).toBe('Based on the available documents, the most relevant information comes from "two": apples and bananas and cherries. However, a more specific answer would require additional context.');
  });

  it('ignores question words of two letters or fewer', async () => {
    const { qaService } = await indexed({ 'a.txt': 'is an ox' });
    const r = await qaService.ask('is an ox');
    expect(r.citations).toEqual([]);
    expect(r.confidence).toBe(0.3);
  });

  it('pattern answers append the first citation when there is one', async () => {
    const { qaService } = await indexed({ 'notes.txt': 'The meeting covered the roadmap.' });
    const r = await qaService.ask('meeting summary');
    expect(r.answer).toMatch(/^The meeting summary indicates/);
    expect(r.answer).toContain('Based on the document "notes", The meeting covered the roadmap..');
  });

  it('truncates excerpts to 200 characters', async () => {
    const long = 'keyword ' + 'z'.repeat(400);
    const { qaService } = await indexed({ 'long.txt': long });
    const r = await qaService.ask('keyword');
    expect(r.citations[0].excerpt).toBe(long.substring(0, 200));
  });

  it('uses "Unknown Document" when a chunk has no document metadata', async () => {
    const { qaService, persistence } = await indexed({ 'a.txt': 'orphan content' });
    persistence.writeJson('documents-meta.json', []);
    const r = await qaService.ask('orphan');
    expect(r.citations[0].documentTitle).toBe('Unknown Document');
  });

  it('saves every exchange to history and clearHistory empties it', async () => {
    const { qaService } = makeServices(tempDir());
    const a = await qaService.ask('first question');
    const b = await qaService.ask('second question');
    expect(qaService.getHistory()).toEqual([
      { question: 'first question', response: a },
      { question: 'second question', response: b },
    ]);
    expect(qaService.hasAnswer(a.id)).toBe(true);
    expect(qaService.hasAnswer('nope')).toBe(false);
    qaService.clearHistory();
    expect(qaService.getHistory()).toEqual([]);
    expect(qaService.hasAnswer(a.id)).toBe(false);
  });

  it('getHistory does not rewrite history when every entry already has an id', async () => {
    const { qaService, persistence } = makeServices(tempDir());
    await qaService.ask('q');
    const write = vi.spyOn(persistence, 'writeJson');
    qaService.getHistory();
    expect(write).not.toHaveBeenCalled();
  });
});
