import { beforeEach, describe, expect, it } from 'vitest';
import { FeedbackService, FEEDBACK_FILE } from '../../src/services/feedback-service';
import { PersistenceService } from '../../src/services/persistence-service';
import { quietLogs, tempDir } from '../helpers';

beforeEach(() => quietLogs());

function make(known: string[] = ['a1', 'a2']) {
  const persistence = new PersistenceService(tempDir());
  return { persistence, fb: new FeedbackService(persistence, id => known.includes(id)) };
}

describe('FeedbackService (unit)', () => {
  it('list is empty when nothing was submitted', () => {
    expect(make().fb.list()).toEqual([]);
  });

  it('stores entries in feedback.json, one per answer', () => {
    const { fb, persistence } = make();
    fb.submit('a1', 'up');
    fb.submit('a2', 'down');
    const replaced = fb.submit('a1', 'down');
    expect(fb.list()).toEqual([{ answerId: 'a2', rating: 'down', timestamp: expect.any(String) }, replaced]);
    expect(persistence.readJson(FEEDBACK_FILE)).toEqual(fb.list());
  });

  it.each([[undefined], [42], [''], ['   ']])('rejects answerId %j', bad => {
    const { fb } = make();
    expect(() => fb.submit(bad, 'up')).toThrow('answerId must be a non-empty string');
    expect(fb.list()).toEqual([]);
  });

  it.each([['meh'], [undefined], [1]])('rejects rating %j', bad => {
    const { fb } = make();
    expect(() => fb.submit('a1', bad)).toThrow("rating must be 'up' or 'down'");
  });

  it('rejects unknown answers', () => {
    const { fb } = make();
    expect(() => fb.submit('zzz', 'up')).toThrow('No answer with id zzz');
    expect(fb.list()).toEqual([]);
  });
});
